CREATE TABLE IF NOT EXISTS sys_user (id BIGINT PRIMARY KEY AUTO_INCREMENT, username VARCHAR(64) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, nickname VARCHAR(100), display_name VARCHAR(100), phone VARCHAR(30), email VARCHAR(120), department VARCHAR(100), department_id BIGINT NULL, status TINYINT DEFAULT 1, enabled TINYINT DEFAULT 1, create_time DATETIME NULL, update_time DATETIME NULL);
CREATE TABLE IF NOT EXISTS sys_product (id BIGINT PRIMARY KEY AUTO_INCREMENT, sku VARCHAR(64) UNIQUE, name VARCHAR(200) NOT NULL, category VARCHAR(100), unit VARCHAR(20), reference_price DECIMAL(12,2), stock INT DEFAULT 0, active TINYINT DEFAULT 1);
CREATE TABLE IF NOT EXISTS sys_supplier (id BIGINT PRIMARY KEY AUTO_INCREMENT, code VARCHAR(64) UNIQUE, name VARCHAR(200) NOT NULL, contact VARCHAR(100), phone VARCHAR(30), address VARCHAR(255), active TINYINT DEFAULT 1);
CREATE TABLE IF NOT EXISTS purchase_request (id BIGINT PRIMARY KEY AUTO_INCREMENT, request_no VARCHAR(64) NOT NULL UNIQUE, applicant_id BIGINT NOT NULL, department_id BIGINT, reason VARCHAR(500) NOT NULL, total_amount DECIMAL(14,2) NOT NULL DEFAULT 0, status VARCHAR(20) NOT NULL, version INT NOT NULL DEFAULT 0, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, INDEX idx_request_applicant(applicant_id), INDEX idx_request_status(status));
CREATE TABLE IF NOT EXISTS purchase_request_item (id BIGINT PRIMARY KEY AUTO_INCREMENT, request_id BIGINT NOT NULL, product_id BIGINT NOT NULL, product_name VARCHAR(200) NOT NULL, quantity INT NOT NULL, unit_price DECIMAL(14,2) NOT NULL, amount DECIMAL(14,2) NOT NULL, INDEX idx_request_item_request(request_id));
CREATE TABLE IF NOT EXISTS approval_record (id BIGINT PRIMARY KEY AUTO_INCREMENT, request_id BIGINT NOT NULL, approver_id BIGINT NOT NULL, action VARCHAR(20) NOT NULL, comment VARCHAR(500), created_at DATETIME NOT NULL, INDEX idx_approval_request(request_id));
CREATE TABLE IF NOT EXISTS purchase_order (id BIGINT PRIMARY KEY AUTO_INCREMENT, order_no VARCHAR(64) NOT NULL UNIQUE, request_id BIGINT NOT NULL, supplier_id BIGINT NOT NULL, total_amount DECIMAL(14,2) NOT NULL, status VARCHAR(20) NOT NULL, version INT NOT NULL DEFAULT 0, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, INDEX idx_order_request(request_id));
CREATE TABLE IF NOT EXISTS purchase_order_item (id BIGINT PRIMARY KEY AUTO_INCREMENT, order_id BIGINT NOT NULL, product_id BIGINT NOT NULL, product_name VARCHAR(200) NOT NULL, quantity INT NOT NULL, unit_price DECIMAL(14,2) NOT NULL, amount DECIMAL(14,2) NOT NULL, INDEX idx_order_item_order(order_id));
CREATE TABLE IF NOT EXISTS inventory_stock (product_id BIGINT PRIMARY KEY, quantity INT NOT NULL DEFAULT 0, version INT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS inventory_transaction (id BIGINT PRIMARY KEY AUTO_INCREMENT, product_id BIGINT NOT NULL, type VARCHAR(10) NOT NULL, quantity INT NOT NULL, reference_no VARCHAR(64) NOT NULL, operator_id BIGINT, created_at DATETIME NOT NULL, INDEX idx_inventory_tx_product(product_id));

CREATE TABLE IF NOT EXISTS sys_department (id BIGINT PRIMARY KEY AUTO_INCREMENT, parent_id BIGINT NULL, name VARCHAR(100) NOT NULL, status TINYINT NOT NULL DEFAULT 1, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sys_role (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(64) NOT NULL, code VARCHAR(64) NOT NULL UNIQUE, status TINYINT NOT NULL DEFAULT 1, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sys_user_role (user_id BIGINT NOT NULL, role_id BIGINT NOT NULL, PRIMARY KEY(user_id,role_id));
CREATE TABLE IF NOT EXISTS sys_role_permission (role_id BIGINT NOT NULL, permission_id BIGINT NOT NULL, PRIMARY KEY(role_id,permission_id));
CREATE TABLE IF NOT EXISTS sys_menu (id BIGINT PRIMARY KEY AUTO_INCREMENT, parent_id BIGINT NULL, name VARCHAR(64) NOT NULL, path VARCHAR(255), icon VARCHAR(128), permission_code VARCHAR(128), sort_order INT DEFAULT 0, status TINYINT NOT NULL DEFAULT 1, create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sys_config (id BIGINT PRIMARY KEY AUTO_INCREMENT, config_key VARCHAR(128) NOT NULL UNIQUE, config_value TEXT NOT NULL, description VARCHAR(255), create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sys_operation_log (id BIGINT PRIMARY KEY AUTO_INCREMENT, operator VARCHAR(100), action VARCHAR(100), resource VARCHAR(255), created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
INSERT IGNORE INTO sys_config(config_key,config_value,description) VALUES ('system.name','企业采购与审批管理系统','系统名称');
